actions.script:
import groovy.json.JsonOutput
import java.security.MessageDigest

def runValue = ec.entity.makeValue('moqui.math.MathModelRun')
        .setAll([mathModelId: 'MM_CODE_SECURE_CODING_COMPLIANCE',
                 startTime: ec.user.nowTimestamp, parameters: JsonOutput.toJson([graphId: graphId]),
                 hasError: 'N'])
runValue.setSequencedIdPrimary()
runValue.create()
mathModelRunId = runValue.mathModelRunId

try {
    String crosswalkGraphId = 'CyberPlcNormCrosswalk'
    if (!ec.entity.find('moqui.math.Graph').condition('graphId', crosswalkGraphId).one()) {
        ec.entity.makeValue('moqui.math.Graph')
                .setAll([graphId: crosswalkGraphId, graphTypeEnumId: 'GtDirected',
                         name: 'PLC-to-Norm Crosswalk', loopsAllowed: 'N',
                         description: 'Crosswalk edges linking PLC/firmware graph vertices to normative clause vertices, without merging either source graph.'])
                .create()
    }

    // rule_id / pattern -> [documentId, clauseNumber], verified real clauses (see description).
    Map<String, List<String>> ruleToClause = [
        C_UNBOUNDED_COPY:           ['IEC-62443-4-1', '8.4.1'],
        C_PLAINTEXT_NETWORK_SCHEME: ['IEC-62443-4-2', '8.2'],
        CREDENTIAL_LIKE_SYMBOL:     ['IEC-62443-3-3', '5.9.3.1']
    ]

    Closure<String> findClauseVertexId = { String documentId, String clauseNumber ->
        def row = ec.entity.find('moqui.cyber.graph.CyberNormVertexMeta')
                .condition('documentId', documentId).condition('clauseNumber', clauseNumber)
                .condition('vertexType', 'NormClause').one()
        row?.graphVertexId as String
    }

    Closure<Void> ensureEdge = { String fromVertexId, String toVertexId, String rationale ->
        // Check by (graphId, fromVertexId, toVertexId, label) first, not just the derived
        // edgeId - CyberPlcNormCrosswalkDemoSeedData.xml's one hand-made edge
        // (EDGE_PLC_NORM_1) uses an arbitrary id, not this hash scheme, and must be
        // recognized as the same real edge rather than duplicated.
        def existingEdge = ec.entity.find('moqui.math.GraphEdge').condition('graphId', crosswalkGraphId)
                .condition('fromVertexId', fromVertexId).condition('toVertexId', toVertexId)
                .condition('label', 'VIOLATES_SECURE_CODING_RULE').one()
        String edgeId = existingEdge?.graphEdgeId as String
        if (!existingEdge) {
            String source = "${crosswalkGraphId}|VIOLATES_SECURE_CODING_RULE|${fromVertexId}|${toVertexId}"
            edgeId = MessageDigest.getInstance('SHA-1').digest(source.getBytes('UTF-8')).encodeHex().toString()
            ec.entity.makeValue('moqui.math.GraphEdge')
                    .setAll([graphEdgeId: edgeId, graphId: crosswalkGraphId, edgeTypeEnumId: 'GetDirected',
                             isDirected: 'Y', isLoop: 'N', fromVertexId: fromVertexId, toVertexId: toVertexId,
                             label: 'VIOLATES_SECURE_CODING_RULE'])
                    .create()
            ec.entity.makeValue('moqui.math.Parameter')
                    .setAll([parameterId: ec.entity.sequencedIdPrimary('moqui.math.Parameter', null, null),
                             parameterDefId: 'CyberNormRationaleParam', graphId: crosswalkGraphId,
                             graphEdgeId: edgeId, textValue: rationale])
                    .create()
            edgesCreated = (edgesCreated ?: 0) + 1
        }
    }
    edgesCreated = 0

    List<Map> findingList = []

    ec.entity.find('moqui.plc.graph.PlcGraphVertexMeta')
            .condition('graphId', graphId).condition('vertexType', 'SecurityObservation')
            .list().each { obs ->
        String ruleId = obs.qualifiedName ? (obs.qualifiedName as String).split('@')[0] : null
        List<String> clause = ruleId ? ruleToClause[ruleId] : null
        Map<String, Object> finding = [graphVertexId: obs.graphVertexId, ruleId: ruleId,
                qualifiedName: obs.qualifiedName]
        if (clause) {
            String clauseVertexId = findClauseVertexId(clause[0], clause[1])
            if (clauseVertexId) {
                ensureEdge(obs.graphVertexId as String, clauseVertexId,
                        "Parser-detected ${ruleId} finding, real structural rule (see parser/c_firmware_parser.py), crosswalked to ${clause[0]} ${clause[1]}.")
                finding.crosswalkedTo = "${clause[0]} ${clause[1]}"
            } else {
                finding.crosswalkedTo = null
                finding.note = 'Mapped norm clause not found in loaded corpus.'
            }
        } else {
            finding.crosswalkedTo = null
            finding.note = 'No verified norm clause mapping for this rule (honest gap, not forced).'
        }
        findingList.add(finding)
    }

    ec.entity.find('moqui.plc.graph.PlcGraphVertexMeta')
            .condition('graphId', graphId).condition('vertexType', 'Symbol').condition('codeKind', 'Variable')
            .list().findAll { sym ->
                sym.canonicalName && (sym.canonicalName as String) ==~ /(?i).*(password|secret|credential|token|apikey).*/
            }.each { sym ->
        List<String> clause = ruleToClause['CREDENTIAL_LIKE_SYMBOL']
        String clauseVertexId = findClauseVertexId(clause[0], clause[1])
        Map<String, Object> finding = [graphVertexId: sym.graphVertexId, ruleId: 'CREDENTIAL_LIKE_SYMBOL',
                qualifiedName: sym.qualifiedName]
        if (clauseVertexId) {
            ensureEdge(sym.graphVertexId as String, clauseVertexId,
                    "${sym.qualifiedName} is a Symbol/Variable whose name matches a credential-like pattern; ${clause[0]} ${clause[1]} requires password generation/lifetime controls a hardcoded value structurally cannot satisfy.")
            finding.crosswalkedTo = "${clause[0]} ${clause[1]}"
        } else {
            finding.crosswalkedTo = null
            finding.note = 'Mapped norm clause not found in loaded corpus.'
        }
        findingList.add(finding)
    }

    findings = findingList

    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, results: JsonOutput.toJson(
                    [graphId: graphId, findingCount: findingList.size(), edgesCreated: edgesCreated])])
            .update()
} catch (Throwable t) {
    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()])
            .update()
    throw t
}
